\xymatrix{
Rf_*K \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*L \otimes_{\mathcal{O}'}^\mathbf{L}
Rf_*M \ar[r] \ar[d] &
Rf_*(K \otimes_\mathcal{O}^\mathbf{L} L)
\otimes_{\mathcal{O}'}^\mathbf{L} Rf_*M \ar[d] \\
Rf_*K \otimes_{\mathcal{O}'}^\mathbf{L}
